create table if not exists spiritual.quran_bookmarks ( id bigint generated always as identity primary key, ayah_id integer not null, surah_id smallint, ayah_number smallint, ayah_text text, label text, tags text[], color text, user_id uuid not null references identity.profiles (id) default auth.uid(), tenant_id uuid references core.tenants (id), created_at timestamptz default now(), updated_at timestamptz default now(), unique (user_id, ayah_id) );
